import sys
import sqlite3
import json
import logging
from datetime import datetime

def parse_filters(filters):
    query_parts = []
    for col, val in filters.items():
        if isinstance(val, str):
            query_parts.append(f"{col} = ?")
        else:
            query_parts.append(f"{col} = ?")
    return query_parts

def execute_query(db_path, query_json):
    try:
        with open(query_json, 'r') as f:
            query_data = json.load(f)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in query file: {e}", file=sys.stderr)
        sys.exit(1)
    except IOError as e:
        print(f"Error: Could not read query file: {e}", file=sys.stderr)
        sys.exit(1)

    table = query_data.get("table")
    columns = query_data.get("columns", [])
    filters = query_data.get("filters", {})

    if not table:
        print("Error: Missing 'table' key in query file", file=sys.stderr)
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        print(f"Error: Could not open database: {e}", file=sys.stderr)
        sys.exit(1)

    params = []
    conditions = []
    for col, val in filters.items():
        if col not in columns:
            print(f"Error: Column '{col}' not in selected columns", file=sys.stderr)
            sys.exit(1)
        if isinstance(val, str):
            params.append(val)
        else:
            params.append(val)

        conditions.append(f"{col} = ?")

    if conditions:
        query = f"SELECT {', '.join(columns)} FROM {table} WHERE {' AND '.join(conditions)}"
    else:
        query = f"SELECT {', '.join(columns)} FROM {table}"

    try:
        cursor.execute(query, params)
        rows = cursor.fetchall()
        conn.close()
    except sqlite3.Error as e:
        print(f"Error: Query failed: {e}", file=sys.stderr)
        sys.exit(1)

    return rows

def log_result(rows):
    timestamp = datetime.now().isoformat() + "Z"
    with open("filter_db.log", "a") as log_file:
        log_file.write(f"{timestamp} OK {len(rows)}\n")

def main():
    if len(sys.argv) != 3:
        print("Usage: python filter_db.py <database_path> <query_json>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    query_json = sys.argv[2]

    rows = execute_query(db_path, query_json)

    for row in rows:
        print(json.dumps(dict(zip(query_data["columns"], row))))

    log_result(rows)

if __name__ == "__main__":
    try:
        with open(sys.argv[2], 'r') as f:
            query_data = json.load(f)
    except:
        sys.exit(1)

    main()
